class Solution {
public:
    vector<int> solveQueries(vector<int>& nums, vector<int>& queries) {
        int n = nums.size();
        unordered_map<int, vector<int>> pos;
        pos.reserve(n);
        for (int i = 0; i < n; i++) {
            pos[nums[i]].push_back(i);
        }
        vector<int> ans(n, -1);
        for (auto& kv : pos) {
            vector<int>& idxs = kv.second;
            int k = idxs.size();
            if (k < 2) continue;
            for (int j = 0; j < k; j++) {
                int cur = idxs[j];
                int prevIdx = idxs[(j - 1 + k) % k];
                int nextIdx = idxs[(j + 1) % k];
                int d1 = abs(cur - prevIdx);
                d1 = min(d1, n - d1);
                int d2 = abs(cur - nextIdx);
                d2 = min(d2, n - d2);
                int best = min(d1, d2);
                if (ans[cur] == -1 || best < ans[cur]) {
                    ans[cur] = best;
                }
            }
        }
        vector<int> result;
        result.reserve(queries.size());
        for (int q : queries) {
            result.push_back(ans[q]);
        }
        return result;
    }
};
